// NewSPL1Lexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func SPL1LexerInit() {
	staticData := &SPL1LexerLexerStaticData
	staticData.once.Do(spl1lexerLexerInit)
}

// NewSPL1Lexer produces a new lexer instance for the optional input antlr.CharStream.
func NewSPL1Lexer(input antlr.CharStream) *SPL1Lexer {
	SPL1LexerInit()
	l := new(SPL1Lexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &SPL1LexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "SPL1.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

